#include <stdio.h>
int main() {
  int arr[] = {10, 20, 30, 40, 50};
  int *ptr = arr;
  printf("Value at ptr: %d\n", *ptr); // Accesses arr[0]
  ptr++;
  printf("Value at ptr after increment: %d\n", *ptr); // Accesses arr[1]
  ptr += 2; 
  printf("Value at ptr after adding 2: %d\n", *ptr); // Accesses arr[3]
  ptr = arr + 4; // Points to the last element
  printf("Value at ptr pointing to the last element: %d\n", *ptr); // Accesses arr[4]
  int diff = ptr - arr; // Number of elements between ptr and arr
  printf("Difference between pointers: %d\n", diff);
  return 0;
}
